package studio.solocamera;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.io.*;import java.lang.reflect.*;
/** Reproduces the post-insert playhead, rather than testing only playback from zero. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class EditorPlaybackChecks {
 /** A valid source that deliberately waits for metadata, to model a slow/unavailable accent. */
 static final class WaitingSource extends androidx.media3.exoplayer.source.BaseMediaSource {
  public androidx.media3.common.MediaItem getMediaItem(){return androidx.media3.common.MediaItem.EMPTY;}
  protected void prepareSourceInternal(androidx.media3.datasource.TransferListener listener){}
  protected void releaseSourceInternal(){}
  public void maybeThrowSourceInfoRefreshError(){}
  public androidx.media3.exoplayer.source.MediaPeriod createPeriod(androidx.media3.exoplayer.source.MediaSource.MediaPeriodId id,androidx.media3.exoplayer.upstream.Allocator allocator,long start){throw new AssertionError("No timeline supplied");}
  public void releasePeriod(androidx.media3.exoplayer.source.MediaPeriod period){}
 }

 interface Action{void run()throws Exception;}
 static void ui(Instrumentation h,Action f){Throwable[] e={null};h.runOnMainSync(()->{try{f.run();}catch(Throwable x){e[0]=x;}});if(e[0]!=null)throw new RuntimeException(e[0]);}
 static Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}static void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}static void call(Object o,String name)throws Exception{Method m=o.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(o);}
 static void check(boolean v,String message){if(!v)throw new AssertionError(message);}static void stage(Instrumentation h,String text){Bundle b=new Bundle();b.putString("stage",text);h.sendStatus(0,b);}
 static EditorLivePreview preview(EditorActivity a)throws Exception{return (EditorLivePreview)get(a,"livePreview");}
 static void start(Instrumentation h,EditorActivity a,EditorProject p,long at)throws Exception{ui(h,()->{set(a,"project",p);set(a,"editing",true);set(a,"selectedCaption",p.captions.isEmpty()?-1:0);set(a,"selectedTrack",p.captions.isEmpty()?"Video":"Text");set(a,"position",at);call(a,"showEditor");});Thread.sleep(300);ui(h,()->{EditorLivePreview v=preview(a);check(v!=null,"Missing live preview active="+get(a,"active")+" editing="+get(a,"editing")+" exporting="+get(a,"exporting")+" message="+((android.widget.TextView)get(a,"message")).getText());v.seekTo(at);((View)get(a,"play")).performClick();check(v.isPlaying(),"Play button did not start playback");});}
 static void advances(Instrumentation h,EditorActivity a,long minimum,long wait)throws Exception{Thread.sleep(wait);ui(h,()->{EditorLivePreview v=preview(a);check(v.position()>=minimum,"Frozen playback: "+v.diagnostics());});}
 static void real(Instrumentation h,Bundle result)throws Exception{
  EditorActivity a=(EditorActivity)h.startActivitySync(new Intent(h.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));EditorProject p=EditorProject.from(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("/data/local/tmp/playback-project.json")),java.nio.charset.StandardCharsets.UTF_8));p.id="77777777-7777-4777-8777-777777777752";
  try{android.media.MediaExtractor extractor=new android.media.MediaExtractor();try{extractor.setDataSource(a,android.net.Uri.parse(p.clips.get(0).uri),null);for(int i=0;i<extractor.getTrackCount();i++){stage(h,"Source track "+i+" "+extractor.getTrackFormat(i));extractor.selectTrack(i);StringBuilder times=new StringBuilder();for(int n=0;n<12;n++){times.append(extractor.getSampleTime()).append(',');extractor.advance();}stage(h,"Source timestamps "+times);extractor.unselectTrack(i);}}finally{extractor.release();}for(long at:new long[]{0,650,12000}){stage(h,"User project playback at "+at);start(h,a,p,at);Thread.sleep(1200);ui(h,()->{EditorLivePreview v=preview(a);Object layer=get(v,"mainLayer");androidx.media3.exoplayer.ExoPlayer decoder=(androidx.media3.exoplayer.ExoPlayer)get(layer,"decoder");stage(h,v.diagnostics()+" buffered="+decoder.getBufferedPosition()+" loading="+decoder.isLoading()+" tracks="+decoder.getCurrentTracks().getGroups().size()+" playWhenReady="+decoder.getPlayWhenReady()+" suppressed="+decoder.getPlaybackSuppressionReason());});advances(h,a,at+500,8000);ui(h,()->{stage(h,preview(a).diagnostics());check(preview(a).renderedFrames>2,"No decoded user video frames");preview(a).pause();});}result.putString("checks","PASS user project video playback from start and seek, actual play button and decoded frames");}finally{ui(h,a::finish);new File(a.getFilesDir(),"edit-projects/"+p.id+".json").delete();}
 }
 static void run(Instrumentation h,Bundle result)throws Exception{
  EditorActivity a=(EditorActivity)h.startActivitySync(new Intent(h.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));EditorFonts.init(a);File dir=new File(a.getCacheDir(),"editor-playback-qa");dir.mkdirs();EditorProject p=new EditorProject();p.id="77777777-7777-4777-8777-777777777751";p.name="Playback regression QA";p.aspect=2;p.height=720;EditorProject.Caption title=new EditorProject.Caption();title.type="Text";title.style=EditorTitlePresets.create(88,3000);title.at=0;title.end=3000;p.captions.add(title);
  try{
   for(long at:new long[]{0,300,650,850}){stage(h,"Play title from "+at+"ms, including post-insert position");start(h,a,p,at);advances(h,a,at+500,1400);ui(h,()->{EditorLivePreview v=preview(a);((View)get(a,"play")).performClick();check(!v.isPlaying(),"Pause button failed");});long[] paused={0};ui(h,()->paused[0]=preview(a).position());Thread.sleep(180);ui(h,()->{check(preview(a).position()==paused[0],"Pause continued advancing");((View)get(a,"play")).performClick();});advances(h,a,paused[0]+300,850);}
   stage(h,"A buffering preset sound must not block video");start(h,a,p,650);ui(h,()->{Object sounds=get(preview(a),"titleSounds");java.util.Map<?,?> entries=(java.util.Map<?,?>)get(sounds,"entries");Object entry=entries.get(title);check(entry!=null,"Missing preset sound entry");androidx.media3.exoplayer.ExoPlayer old=(androidx.media3.exoplayer.ExoPlayer)get(entry,"player");old.release();androidx.media3.exoplayer.ExoPlayer blocked=new androidx.media3.exoplayer.ExoPlayer.Builder(a).build();blocked.setMediaSource(new WaitingSource());blocked.prepare();set(entry,"player",blocked);});advances(h,a,1150,1400);
   stage(h,"Replay after end and repeated scrubbing");ui(h,()->{EditorLivePreview v=preview(a);v.pause();v.seekTo(p.duration());((View)get(a,"play")).performClick();});advances(h,a,500,1300);for(long at:new long[]{720,100,850}){ui(h,()->{EditorLivePreview v=preview(a);v.pause();v.seekTo(at);((View)get(a,"play")).performClick();});advances(h,a,at+350,1000);}
   stage(h,"Video, overlay and preset sound together");ui(h,()->call(a,"releasePlayer"));Method source=CreatorExpansionChecks.class.getDeclaredMethod("colorVideo",Instrumentation.class,File.class,String.class,int.class);source.setAccessible(true);File video=(File)source.invoke(null,h,dir,"source",Color.rgb(40,110,170));EditorProject.Clip clip=new EditorProject.Clip(video.getAbsolutePath(),"Playback video",2400);clip.width=640;clip.height=360;p.clips.add(clip);EditorProject.Overlay overlay=new EditorProject.Overlay();overlay.clip=clip.copy();overlay.at=0;overlay.scale=.35;p.overlays.add(overlay);title.end=2400;title.style.duration=title.style.end=2400;start(h,a,p,650);int[] frames={0};ui(h,()->frames[0]=preview(a).renderedFrames);advances(h,a,1150,1300);ui(h,()->check(preview(a).renderedFrames>frames[0]+3,"Video frames not updating: "+preview(a).diagnostics()));
   stage(h,"Imported audio and mute during playback");EditorProject.Audio audio=new EditorProject.Audio();audio.uri=EditorTitleSounds.file(title.style).getAbsolutePath();audio.name="Test sound";audio.duration=audio.end=950;audio.start=0;audio.at=1000;p.audios.add(audio);start(h,a,p,650);advances(h,a,1300,1600);ui(h,()->{preview(a).pause();preview(a).seekTo(650);preview(a).muteMonitoring(true);((View)get(a,"play")).performClick();});advances(h,a,1100,1200);ui(h,()->{preview(a).pause();preview(a).seekTo(650);preview(a).muteMonitoring(false);title.style.titleSound=false;((View)get(a,"play")).performClick();});advances(h,a,1100,1200);
   result.putString("checks","PASS actual Play/Pause button, post-insert 650ms playback, late sound starts, pause/resume, replay after end, scrubbing, video frame delivery, overlay + title sound + imported audio and mute");
  }finally{ui(h,a::finish);new File(a.getFilesDir(),"edit-projects/"+p.id+".json").delete();}
 }
}
